local config = {
  str_homestory_N17guide_90000101_1_dialog_content = "...",
  str_homestory_N17guide_90000101_2_dialog_content = "Hmm...",
  str_homestory_N17guide_90000101_3_dialog_content = "Vice?",
  str_homestory_N17guide_90000101_4_dialog_content = "What are you looking at?",
  str_homestory_N17guide_90000101_5_dialog_content = "Such a huge expanse of land... I didn't think Eraveil had a place like this!",
  str_homestory_N17guide_90000101_6_dialog_content = "How did we not notice it in all of our adventures?!",
  str_homestory_N17guide_90000101_7_dialog_content = "You don't have any memory of such a place? Eraveil's your hometown after all...",
  str_homestory_N17guide_90000101_8_option_content = "I remember.",
  str_homestory_N17guide_90000101_9_dialog_content = "I suppose you could say I have a slight impression of it. The structures and flora here feel quite familiar.",
  str_homestory_N17guide_90000101_10_dialog_content = "But I can't put my finger on where I've seen them before... Maybe I'm mistaken.",
  str_homestory_N17guide_90000101_11_dialog_content = "After all, this isn't the same Eraveil we've seen before, so my memories may not be so reliable.",
  str_homestory_N17guide_90000101_12_dialog_content = "That makes sense. You were really young then, and this place was very well-hidden...",
  str_homestory_N17guide_90000101_13_option_content = "I don't remember.",
  str_homestory_N17guide_90000101_14_dialog_content = "I don't think I've ever seen this place.",
  str_homestory_N17guide_90000101_15_dialog_content = "The vague memories I have of Eraveil are of its other areas. I don't think I ever came here when I was young.",
  str_homestory_N17guide_90000101_16_dialog_content = "That makes sense, this place was always very well-hidden.",
  str_homestory_N17guide_90000101_17_dialog_content = "Eraveil is truly mysterious. There are always surprises waiting for us.",
  str_homestory_N17guide_90000101_18_dialog_content = "I can't wait to explore this place!<sprite=emo_aixin size=60 />",
  str_homestory_N17guide_90000101_19_dialog_content = "Has your inner Illumina Exploration team spirit awakened again?",
  str_homestory_N17guide_90000101_20_dialog_content = "Creak, creak...",
  str_homestory_N17guide_90000101_21_dialog_content = "Huh? What's that?",
  str_homestory_N17guide_90000101_22_dialog_content = "It looks like some kind of automated... machine? Or creature?",
  str_homestory_N17guide_90000101_23_dialog_content = "Chubb, Chubb!",
  str_homestory_N17guide_90000101_24_dialog_content = "It's speaking!",
  str_homestory_N17guide_90000101_25_dialog_content = "Welcome, welcome! Chubb! Chubb!",
  str_homestory_N17guide_90000101_26_dialog_content = "It looks really happy. I thought it was a defensive device that would mark us as hostile...",
  str_homestory_N17guide_90000101_27_dialog_content = "If I'm not mistaken, it's made from Caelestite technology. Just look at the material it's made of...",
  str_homestory_N17guide_90000101_28_dialog_content = "The markings too... I think I've seen something similar on the Colossus...",
  str_homestory_N17guide_90000101_29_dialog_content = "But its silly appearance is really something, huh?",
  str_homestory_N17guide_90000101_30_dialog_content = "Chubb!! Who are you calling silly, Chubb!!<sprite=emo_nuhuo size=60 />",
  str_homestory_N17guide_90000101_31_dialog_content = "It's angry. It's got a huge temper for such a little thing.",
  str_homestory_N17guide_90000101_32_dialog_content = "Let's have a look around. May we? ... Er...",
  str_homestory_N17guide_90000101_33_dialog_content = "Hmm, what should I call you?",
  str_homestory_N17guide_90000101_34_dialog_content = "Chubb.",
  str_homestory_N17guide_90000101_35_dialog_content = "... Chubb? Did you make that up on the spot?",
  str_homestory_N17guide_90000101_36_dialog_content = "It keeps saying \"Chubb.\"",
  str_homestory_N17guide_90000101_37_dialog_content = "Chubb! Nice name, Chubb!<sprite=emo_aixin size=60 />",
  str_homestory_N17guide_90000101_38_dialog_content = "It actually likes this name?",
  str_homestory_N17guide_90000101_39_dialog_content = "I guess it's accepted us!",
  str_homestory_N17guide_90000101_40_dialog_content = "Let's go, PlayerName! Let's have a look around!",
  str_homestory_N17guide_90000102_0_dialog_content = "Vice...",
  str_homestory_N17guide_90000102_1_dialog_content = "I've already spoken to Chubb here.",
  str_homestory_N17guide_90000102_2_dialog_content = "I pretty much got what it meant to say... It's actually very simple!",
  str_homestory_N17guide_90000102_3_dialog_content = "What? You guys are conversing now?",
  str_homestory_N17guide_90000102_4_dialog_content = "It learned Universese really quickly. It even gave me an <color=#FFB400>axe</color> and a <color=#FFB400>pickaxe</color>.",
  str_homestory_N17guide_90000102_5_dialog_content = "An axe and a pickaxe?",
  str_homestory_N17guide_90000102_6_dialog_content = "Yeah. I think it's for logging? Or digging?<sprite=emo_sikao size=60 />",
  str_homestory_N17guide_90000102_7_dialog_content = "Anyway, I think it wants our help with collecting some <color=#FFB400>materials</color>.",
  str_homestory_N17guide_90000102_8_dialog_content = "Perhaps it's for repairing the buildings here?",
  str_homestory_N17guide_90000102_9_dialog_content = "Anyway, I'll leave it to you, PlayerName. Use it as an opportunity to work out.<sprite=emo_dianzan size=60 />",
  str_homestory_N17guide_90000102_10_dialog_content = "I didn't even get the chance to refuse.<sprite=emo_xiaoku size=60 />",
  str_homestory_N17guide_90000102_11_dialog_content = "I've made a summary of some of the things Chubb told me, and recorded them in this <color=#FFB400>manual</color>.",
  str_homestory_N17guide_90000102_12_dialog_content = "That was fast!",
  str_homestory_N17guide_90000103_1_dialog_content = "Chubb! It's repaired! Hooray! Chubb!<sprite=emo_yinfu size=60 />",
  str_homestory_N17guide_90000103_2_dialog_content = "That was fast! What just happened?",
  str_homestory_N17guide_90000103_3_dialog_content = "I think it repaired the workbench in <color=#FFB400>Hyacinth Tower</color>! Amazing!<sprite=emo_caitiao size=60 />",
  str_homestory_N17guide_90000103_4_dialog_content = "It's not that big of a deal, Chubb...<sprite=emo_guilian size=60 />",
  str_homestory_N17guide_90000103_5_dialog_content = "Hyacinth Tower? Did you come up with that name on the spot too?",
  str_homestory_N17guide_90000103_6_dialog_content = "Nope! Remember the other, larger tower in Eraveil?",
  str_homestory_N17guide_90000103_7_dialog_content = "They look similar, and they're both towers. So, I just named it Hyacinth Tower!",
  str_homestory_N17guide_90000103_8_dialog_content = "But this one before us is obviously much more exquisite. I wonder what it's for...",
  str_homestory_N17guide_90000103_9_dialog_content = "Why don't you give it a try for yourself? Chubb!",
  str_homestory_N17guide_90000103_10_dialog_content = "If it's operated by this Caelestite over here, then it'll definitely work, Chubb!",
  str_homestory_N17guide_90000103_11_dialog_content = "Is that so? Then I'll go ahead!",
  str_homestory_N17guide_90000103_12_dialog_content = "PlayerName, Chubb wants you to try the workbench!",
  str_homestory_N17guide_90000103_13_dialog_content = "It appears to have taken you to be the master of this place.",
  str_homestory_N17guide_90000103_14_dialog_content = "Master...",
  str_homestory_N17guide_90000103_15_dialog_content = "Chubb, Chubb.",
  str_homestory_N17guide_90000103_16_dialog_content = "...",
  str_homestory_N17guide_90000103_17_dialog_content = "That's right, I'm the master of this place now.",
  str_homestory_N17guide_90000103_18_dialog_content = "Sorry to keep you waiting for so long, Chubb.",
  str_homestory_N17guide_90000103_19_dialog_content = "I'm back!<sprite=emo_aixin size=60 />",
  str_homestory_N17guide_90000103_20_dialog_content = "You're back! Chubb!<sprite=emo_yinfu size=60 />",
  str_homestory_N17guide_90000103_21_dialog_content = "So, as the master of this place, are you planning on inviting your friends over to visit?",
  str_homestory_N17guide_90000103_22_dialog_content = "Of course! But where will everyone stay when they come?",
  str_homestory_N17guide_90000103_23_dialog_content = "You can use the workbench to build <color=#FFB400>Gardens Dorm</color>! Chubb!",
  str_homestory_N17guide_90000103_24_dialog_content = "There are <color=#FFB400>dormitories</color> here! This place really has a complete set of facilities!",
  str_homestory_N17guide_90000103_25_dialog_content = "Let's give it a go!",
  str_homestory_N17guide_90000104_1_dialog_content = "<sprite=emo_hanshui size=60 />Phew... It's finally done!",
  str_homestory_N17guide_90000104_2_dialog_content = "I never knew construction was so easy. I expected it to take a really long time.",
  str_homestory_N17guide_90000104_3_dialog_content = "Speaking of which, it was the same on the Colossus when I was renovating rooms. I was able to do it in an instant.",
  str_homestory_N17guide_90000104_4_dialog_content = "Is this the power of technology? We Caelestites really are amazing.",
  str_homestory_N17guide_90000104_5_dialog_content = "Isn't that right, Vi—",
  str_homestory_N17guide_90000104_6_dialog_content = "Vice?<sprite=emo_yihuo size=60 />",
  str_homestory_N17guide_90000104_7_dialog_content = "This way, PlayerName!",
  str_homestory_N17guide_90000104_8_dialog_content = "I can't wait for the others to come check this place out!",
  str_homestory_N17guide_90000104_9_dialog_content = "Hurry up and <color=#FFB400>invite</color> them over!",
  str_homestory_N17guide_90000104_10_dialog_content = "Yeah, alright!",
  str_homestory_N17guide_90000105_1_dialog_content = "Hello, Ms. Blanc. Welcome to...",
  str_homestory_N17guide_90000105_2_dialog_content = "Uh...",
  str_homestory_N17guide_90000105_3_dialog_content = "... My <color=#FFB400>Cloud Gardens</color>.",
  str_homestory_N17guide_90000105_4_dialog_content = "Ha, you're pretty good at making up names on the spot too, PlayerName.",
  str_homestory_N17guide_90000105_5_dialog_content = "I have a good teacher.<sprite=emo_guilian size=60 />",
  str_homestory_N17guide_90000105_6_dialog_content = "Cloud Gardens... Impressive, it's a stylish name.",
  str_homestory_N17guide_90000105_7_dialog_content = "The scenery here is also fantastic. It really makes you temporarily forget all your troubles...",
  str_homestory_N17guide_90000105_8_dialog_content = "Thank you sincerely for inviting me here, PlayerName.",
  str_homestory_N17guide_90000105_9_dialog_content = "Don't mention it, Ms. Blanc. We've always been comrades on our adventures, so now we should farm together too...",
  str_homestory_N17guide_90000105_10_dialog_content = "Ahem!<sprite=emo_shengqi size=60 />",
  str_homestory_N17guide_90000105_11_dialog_content = "... Oh, I meant we can relax and enjoy the scenery together!",
  str_homestory_N17guide_90000105_12_dialog_content = "Haha! No worries! I'll do my part to help Cloud Gardens flourish.",
  str_homestory_N17guide_90000105_13_dialog_content = "I'll take this opportunity to familiarize myself with the surroundings so I can become a good guide for future visitors.",
  str_homestory_N17guide_90000105_14_dialog_content = "Would you introduce me to the other facilities, PlayerName?",
  str_homestory_N17guide_90000105_15_dialog_content = "Allow me, Ms. Blanc. Chubb just told me a lot more!",
  str_homestory_N17guide_90000105_16_dialog_content = "As <color=#FFB400>Hyacinth Tower</color> is gradually perfected, we can use its workbench to <color=#FFB400>unlock even more buildings</color>.",
  str_homestory_N17guide_90000105_17_dialog_content = "The <color=#FFB400>Gardens Dorms</color> we just completed can accommodate everyone who visits!",
  str_homestory_N17guide_90000105_18_dialog_content = "Besides that, we have <color=#FFB400>Fountain of Blessings</color>, located in front of Hyacinth Tower.",
  str_homestory_N17guide_90000105_19_dialog_content = "It has many surprises in store for everyone, and will definitely become a popular tourist spot!",
  str_homestory_N17guide_90000105_20_dialog_content = "There's a <color=#FFB400>museum</color> too. The rare treasures we obtain will be put on display there...",
  str_homestory_N17guide_90000105_21_dialog_content = "Oh, there's more!",
  str_homestory_N17guide_90000105_22_dialog_content = "Vice, slow down. Ms. Blanc can't take it all in so quickly...",
  str_homestory_N17guide_90000105_23_dialog_content = "That's true... Slowly familiarizing myself by experiencing the place in person is also a good idea.",
  str_homestory_N17guide_90000105_24_dialog_content = "PlayerName, are you sure it isn't because you're the one who can't remember everything?",
  str_homestory_N17guide_90000105_25_dialog_content = "<sprite=emo_xuanyun size=60 />I-It is a little overwhelming...",
  str_homestory_N17guide_90000105_26_dialog_content = "I have to remember what every building is for, and also prepare to receive everyone else...",
  str_homestory_N17guide_90000105_27_dialog_content = "I really don't know what to do with you. Here, let me give you this. Keep it safe...",
  str_homestory_N17guide_90000105_28_dialog_content = "You can use this <color=#FFB400>diary</color> to record your daily life in Cloud Gardens!",
  str_homestory_N17guide_90000105_29_dialog_content = "Make records of everything that goes on here so you won't be overwhelmed!",
  str_homestory_N17guide_90000105_30_dialog_content = "How thoughtful of you, Vice.",
  str_homestory_N17guide_90000105_31_dialog_content = "PlayerName, if you're feeling tired, I know the perfect way to help you relax!",
  str_homestory_N17guide_90000105_32_dialog_content = "Huh? What is it?",
  str_homestory_N17guide_90000105_33_dialog_content = "Hehe, follow me if you want to find out!<sprite=emo_yinfu size=60 />",
  str_homestory_N17guide_90000106_0_dialog_content = "Huh?",
  str_homestory_N17guide_90000106_1_dialog_content = "Vice! Your idea of relaxation is...",
  str_homestory_N17guide_90000106_2_dialog_content = "That's right! It's <color=#FFB400>fishing</color>!<sprite=emo_caitiao size=60 />",
  str_homestory_N17guide_90000106_3_dialog_content = "There's nothing more relaxing than enjoying the pleasures of fishing in such a beautiful place.",
  str_homestory_N17guide_90000106_4_dialog_content = "(Besides... the fish we catch can be <color=#FFB400>sold</color>.)<sprite=emo_baiyebi size=60 />",
  str_homestory_N17guide_90000106_5_dialog_content = "(Vice, I can practically smell the greed coming off you.)",
  str_homestory_N17guide_90000106_6_dialog_content = "<sprite=emo_hanshui size=60 />T-That's not the point... Anyway, let's try fishing!!",
  str_homestory_N17guide_90000106_7_dialog_content = "Here are the fishing rods! Let's work up a sweat!",
  str_homestory_N17guide_90000106_8_dialog_content = "I saw a shovel. What's it for?",
  str_homestory_N17guide_90000106_9_dialog_content = "Oh, besides fishing, I plan on digging around. Maybe I'll find treasure.",
  str_homestory_N17guide_90000106_10_dialog_content = "You're making your intentions so obvious...",
  str_homestory_N17guide_90000106_11_dialog_content = "<sprite=emo_shengqi size=60 />Didn't we explore earlier too? It's called hunting for treasure! Hunting for treasure!",
  str_homestory_N17guide_90000106_12_dialog_content = "You don't have to worry if you get lost. Just take a look at your <color=#FFB400>map</color>.",
  str_homestory_N17guide_90000106_13_dialog_content = "Okay, then let's catch some fish first!",
  str_homestory_N17guide_90000107_1_dialog_content = "Yay! The shop is all constructed! This place is slowly coming to life!",
  str_homestory_N17guide_90000107_2_dialog_content = "Yes, indeed, Chubb! We're ready for business now, Chubb!<sprite=emo_caitiao size=60 />",
  str_homestory_N17guide_90000107_3_dialog_content = "Amazingly, Chubbs with different appearances are in charge of different facilities...",
  str_homestory_N17guide_90000107_4_dialog_content = "They're so cute. I'm even considering taking one back to Lumopolis with me!<sprite=emo_aixin size=60 />",
  str_homestory_N17guide_90000107_5_dialog_content = "Chu-Chubb!<sprite=emo_yinfu size=60 />",
  str_homestory_N17guide_90000107_6_dialog_content = "So can I start making money now?",
  str_homestory_N17guide_90000107_7_dialog_content = "Yeah, I've got all the information you need.",
  str_homestory_N17guide_90000107_8_dialog_content = "The shop will regularly display all sorts of <color=#FFB400>orders</color>. You'll be rewarded for completing them.",
  str_homestory_N17guide_90000107_9_dialog_content = "Making money without having to take a step outside! Cloud Gardens is awesome!!<sprite=emo_dianzan size=60 />",
  str_homestory_N17guide_90000107_10_dialog_content = "I didn't expect such a small but fully-stocked store here...",
  str_homestory_N17guide_90000107_11_dialog_content = "I'm even more impressed by Cloud Gardens now...",
  str_homestory_N17guide_90000107_12_dialog_content = "Give it a try, PlayerName! Let's complete an order to start off with!",
  str_homestory_N17guide_90000107_13_dialog_content = "Alright!",
  str_homestory_N17guide_90000107_14_dialog_content = "Actually, why am I always so enthusiastically going off to work?<sprite=emo_tanqi size=60 />",
  str_homestory_N17guide_90000107_15_dialog_content = "This is your own home, PlayerName! Buck up!",
  str_homestory_N17guide_90000108_0_dialog_content = "Done!",
  str_homestory_N17guide_90000108_1_dialog_content = "Whoa! The reward is pretty neat!<sprite=emo_baiyebi size=60 />",
  str_homestory_N17guide_90000108_2_dialog_content = "It feels great to make money with my own two hands!",
  str_homestory_N17guide_90000108_3_dialog_content = "Haven't we set up stalls and fulfilled requests before? I even take everyone to fight in Umbraton every day...",
  str_homestory_N17guide_90000108_4_dialog_content = "It's not the same! This has been a totally new experience!",
  str_homestory_N17guide_90000108_5_dialog_content = "Hmm, I wonder if there are more things in store...",
  str_homestory_N17guide_90000108_6_dialog_content = "Of course there are.",
  str_homestory_N17guide_90000108_7_dialog_content = "Seriously? How do you know so much about this place already?<sprite=emo_yihuo size=60 />",
  str_homestory_N17guide_90000108_8_dialog_content = "You can try <color=#FFB400>planting a tree</color>.",
  str_homestory_N17guide_90000108_9_dialog_content = "The trees here have to be planted? I thought they'd just grow naturally...",
  str_homestory_N17guide_90000108_10_dialog_content = "I'm not talking about any regular tree, but rather...",
  str_homestory_N17guide_90000108_11_dialog_content = "There are these special kinds of trees called <color=#FFB400>Unique Trees</color>. You even have to prepare a special <color=#FFB400>fertile plot</color> just for them.",
  str_homestory_N17guide_90000108_12_dialog_content = "Really? Then let's give it a shot.",
  str_homestory_N17guide_90000108_13_dialog_content = "You know what, I'm kinda tired. I'm heading back to Hyacinth Tower to take a look at the accounts.",
  str_homestory_N17guide_90000108_14_dialog_content = "Vice! Planting trees is physical labor!",
  str_homestory_N17guide_90000108_15_dialog_content = "Caelestite technology is very advanced. There's no need for physical labor.<sprite=emo_qingsong size=60 />",
  str_homestory_N17guide_90000108_16_dialog_content = "Hey—",
  str_homestory_N17guide_90000109_1_dialog_content = "Good work, PlayerName!<sprite=emo_caitiao size=60 />",
  str_homestory_N17guide_90000109_2_dialog_content = "Cloud Gardens has grown so beautiful in such a short span of time!",
  str_homestory_N17guide_90000109_3_dialog_content = "Chubb, Chubb, Chubb!<sprite=emo_yinfu size=60 />",
  str_homestory_N17guide_90000109_4_dialog_content = "You've worked hard too Vice, giving me all the details on this place.",
  str_homestory_N17guide_90000109_5_dialog_content = "It must be really difficult to understand the Chubbs' language, right?",
  str_homestory_N17guide_90000109_6_dialog_content = "You even asked me to help PlayerName handle the arrival of the other Aurorians.",
  str_homestory_N17guide_90000109_8_dialog_content = "So you haven't been slacking off, Vice.",
  str_homestory_N17guide_90000109_9_dialog_content = "Of course not! This is our new home! I have to take good care of it!",
  str_homestory_N17guide_90000109_10_dialog_content = "Besides that, I have to calculate our new incomes and expenditures, not to mention there's still our regular expenses on the Colossus to consider as well...",
  str_homestory_N17guide_90000109_11_dialog_content = "Hmm, should we put up a few Umbraton billboards here and rent them out for people's adverts...?<sprite=emo_tanqi size=60 />",
  str_homestory_N17guide_90000109_12_option_content = "Object",
  str_homestory_N17guide_90000109_13_dialog_content = "N-No! Absolutely not!",
  str_homestory_N17guide_90000109_14_dialog_content = "I'm just joking! I won't ruin your beloved home!",
  str_homestory_N17guide_90000109_15_option_content = "Agree",
  str_homestory_N17guide_90000109_16_dialog_content = "Yes, this place is huge. If we can put up a few billboards...",
  str_homestory_N17guide_90000109_17_dialog_content = "I was joking. Doing that will make this place a second Umbraton.",
  str_homestory_N17guide_90000109_18_dialog_content = "I couldn't bear to ruin your beloved home!",
  str_homestory_N17guide_90000109_19_dialog_content = "We've all got to take good care of everything here, and do our best to make Cloud Gardens flourish!",
  str_homestory_N17guide_90000109_20_dialog_content = "We're ready, Chubb!",
  str_homestory_N17guide_90000109_21_dialog_content = "Vice's enthusiasm is contagious. Even I can't help but feel excited.",
  str_homestory_N17guide_90000109_22_dialog_content = "PlayerName, I hear there are many types of furniture, buildings, and interesting trees still waiting to be discovered in Cloud Gardens.",
  str_homestory_N17guide_90000109_23_dialog_content = "Perhaps we'll one day be able to turn this place into a paradise in Astra.",
  str_homestory_N17guide_90000109_24_dialog_content = "We definitely will!",
  str_homestory_N17guide_90000109_25_dialog_content = "Then let's work hard towards that goal!",
  str_homestory_N17guide_90000109_26_dialog_content = "One, two, three...",
  str_homestory_N17guide_90000109_27_dialog_content = "Let's do this!!<sprite=emo_laba size=60 />"
}
return config
